// Recupera la risposta Anthropic
const anthropicJson = $input.first().json;
const rawText = anthropicJson.content[0].text;

// Pulisce markdown code block se presente
const cleaned = rawText
  .replace(/^```(?:json)?\s*/m, '')
  .replace(/```\s*$/m, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`JSON parse fallito: ${e.message}\nRaw (200 char): ${cleaned.substring(0, 200)}`);
}

// Recupera dati libro dal nodo precedente
const bookData = $('Estrai dati libro').first().json;

return [{
  json: {
    pageId: bookData.pageId,
    bookTitle: bookData.title,
    datiSpremuta: JSON.stringify(parsed)
  }
}];
